  `custom_field` text,
  `adminid` varchar(20) NOT NULL,
  `last_modified` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_agente`),
  KEY `id_agente_coord` (`id_agente_coord`)
) ENGINE=MyISAM;

