DROP TABLE IF EXISTS `gaz_001distinta_base`;
CREATE TABLE IF NOT EXISTS `gaz_001distinta_base` (
  `id` int(10) UNSIGNED ZEROFILL NOT NULL AUTO_INCREMENT,
  `codice_composizione` varchar(32) NOT NULL COMMENT 'è il codice dell''articolo composito',
  `codice_artico_base` varchar(32) NOT NULL COMMENT 'codice dell''articolo base',
  `quantita_artico_base` decimal(14,5) NOT NULL DEFAULT '0.00000' COMMENT 'quantità di articoli base necessari per costituire l''articolo composito',
  `id_movmag` int UNSIGNED DEFAULT NULL COMMENT 'Riferimento ad id_mag del movimento di magazzino. Se =0 indica la struttura di una composizione e verrà utilizzata per generare i relativi movimenti di magazzino, quando valorizzato serve per ricordare l''albero da cui sono stati generati i relativi movimenti di magazzino',
  `sort_order` int NOT NULL COMMENT 'Per ordinamento visualizzazione componente, ad esempio su esplodo della distinta base',
  PRIMARY KEY (`id`),
  KEY `codice_composizione` (`codice_composizione`),
  KEY `codice_artico_base` (`codice_artico_base`),
  KEY `id_movmag` (`id_movmag`),
  KEY `sort_order` (`sort_order`)
) ENGINE=MyISAM COMMENT='Tabella per creare gli "articoli compositi" (distinta base). Un articolo è composito quando è presente in almeno una di queste righe e qundi fa riferimento ad almeno un altro articolo di magazzino. Questi righi si potranno aggiungere tramite lo script admin_artico,  alla fine con il bottone "aggiungi articolo di base" ed immettendo la sola quantità, l''unità di misura ed il prezzo per i documenti di vendita  saranno quelli di sempre ma presi dall''articolo composito, molto facile perchè resterà tutto come prima, mentre la contabilità di magazzino verrà aggiornata tenendo conto di questi righi e non dell''articolo composito.';

