--
-- Struttura della tabella `gaz_001pagame_distribution`
--

DROP TABLE IF EXISTS `gaz_001pagame_distribution`;
CREATE TABLE IF NOT EXISTS `gaz_001pagame_distribution` (
  `id_pagdis` int NOT NULL AUTO_INCREMENT,
  `codpag` int NOT NULL COMMENT 'Referenza alla tabella gaz_001pagame (molti a uno)',
  `descri` varchar(50) NOT NULL DEFAULT '' COMMENT 'La descrizione è indispensabile in assenza di data di scadenza (expiry)',
  `ratperc` decimal(4,1) NOT NULL DEFAULT (0) COMMENT 'La somma dei righi riferiti allo stesso codpag dovrebbe essere 100 se non lo è viene troncato o riempito fino a capienza',
  `from_prev` varchar(3) DEFAULT NULL COMMENT 'Sono i giorni  dalla scadenza precedente o dalla data di riferimento, si può indicare anche una lettere coma nella colonna tiprat di gaz_001pagame. non è indispensabile e se variabile, ovvero non strettamente determinato, es. quando il limite temporale dipende dalla fine dei lavori o da altre condizione queste verranno indicate in descrizione e lasciata vuota o NULL.',
  `tippag` char(1) NOT NULL DEFAULT '0' COMMENT 'La stessa della colonna tippag di gaz_001pagame ma prevale su di essa se valorizzata. Consente metodi di pagamento diversi sulle diverse rate',
  `fae_mode` varchar(4) DEFAULT NULL COMMENT 'Come su gaz_001pagame è il valore MPXX della fattura elettronica. Consente metodi di pagamento diversi sulle diverse rate',
  `id_bank` int NOT NULL,
  `annota` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id_pagdis`) USING BTREE,
  KEY `codpag` (`codpag`),
  KEY `from_prev` (`from_prev`)
) ENGINE=MyISAM COMMENT='Il contenuto di questa tabella serve per gestire i pagamenti con scadenze e rate non costanti nell''importo e nella periodicità. Ed è legata alla tabella gaz_001pagame. Ogni rigo di questa tabella rappresenta una rata per il pagamento riferito con la colonna codpag e verranno passate come matrice alla funzione CalcExpiry nel file expiry_calc.php ';

