--
-- Struttura della tabella `gaz_001rigbro`
--

DROP TABLE IF EXISTS `gaz_001rigbro`;
CREATE TABLE IF NOT EXISTS `gaz_001rigbro` (
  `id_rig` int NOT NULL AUTO_INCREMENT,
  `nrow` int NOT NULL DEFAULT '0' COMMENT 'Numero del rigo sul documento',
  `nrow_linked` int NOT NULL DEFAULT '0' COMMENT 'Numero del rigo al quale è vincolato. Ad esempio un rigo tipo 6 (testo) derivante dalla descrizione estesa di un articolo/servizio di magazzino ',
  `id_tes` int NOT NULL,
  `tiprig` int NOT NULL,
  `codart` varchar(32) NOT NULL DEFAULT '',
  `codice_fornitore` varchar(50) NOT NULL COMMENT 'Mappatura di codart con il codice usato dal fornitore in caso di acquisto, potrebbe essere usato anche per mappare i codici clienti ad es. nella acquisizione ordini da clienti',
  `descri` varchar(1000) NOT NULL COMMENT '1000 caratteri per uniformarsi al tracciato della fattura elettronica',
  `quality` varchar(50) NOT NULL COMMENT 'per indicare la qualità del materiale richiesto, normativa, ecc',
  `id_body_text` int NOT NULL,
  `unimis` char(3) NOT NULL DEFAULT '',
  `larghezza` decimal(10,3) DEFAULT NULL COMMENT 'espresso in mm',
  `lunghezza` decimal(10,3) DEFAULT NULL COMMENT 'espresso in mm',
  `spessore` decimal(10,3) DEFAULT NULL COMMENT 'espresso in mm',
  `peso_specifico` decimal(10,3) DEFAULT NULL COMMENT 'non necessariamente in kg/l, potrà moltiplicare anche con i ml, mq, pezzi',
  `pezzi` int DEFAULT NULL,
  `quanti` decimal(14,5) DEFAULT NULL,
  `prelis` decimal(14,5) DEFAULT '0.00000',
  `sconto` decimal(6,3) DEFAULT '0.000',
  `codvat` int NOT NULL,
  `pervat` decimal(3,1) DEFAULT '0.0',
  `codric` int NOT NULL,
  `provvigione` decimal(4,2) NOT NULL,
  `ritenuta` decimal(3,1) NOT NULL,
  `delivery_date` date DEFAULT '2004-01-27',
  `id_doc` int NOT NULL COMMENT 'può essere usato come riferimento ad un figlio anche se in rigdoc (es. se questo è il rigo di un ordine evaso) o ad un genitore (es. se questo è un task di un diagramma di Gantt sarà l''id_tes in tesbro)',
  `id_mag` int NOT NULL,
  `id_orderman` int DEFAULT NULL COMMENT 'Per avere riferimenti uno a molti, e viceversa, con le produzioni (orderman)',
  `id_rigmoc` int DEFAULT NULL COMMENT 'Riferimento ad id_rig della tabella gaz_NNNrigmoc',
  `custom_field` text COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {"nome_modulo":{"nome_variabile":{"valore_variabile": {}}}}',
  `adminid` varchar(20) NOT NULL DEFAULT '',
  `last_modified` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status` varchar(100) NOT NULL DEFAULT '',
  PRIMARY KEY (`id_rig`) USING BTREE,
  KEY `id_orderman` (`id_orderman`),
  KEY `id_tes` (`id_tes`),
  KEY `id_rigmoc` (`id_rigmoc`),
  KEY `codart` (`codart`),
  KEY `tiprig` (`tiprig`),
  KEY `id_doc` (`id_doc`),
  KEY `id_mag` (`id_mag`),
  KEY `codice_fornitore` (`codice_fornitore`),
  KEY `nrow` (`nrow`),
  KEY `nrow_linked` (`nrow_linked`)
) ENGINE=MyISAM COMMENT='Righi dei documenti le cui testate sono contenute in gaz_NNNtesbro';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001rigdoc`
--

DROP TABLE IF EXISTS `gaz_001rigdoc`;
CREATE TABLE IF NOT EXISTS `gaz_001rigdoc` (
  `id_rig` int NOT NULL AUTO_INCREMENT,
  `nrow` int NOT NULL DEFAULT '0' COMMENT 'Numero del rigo sul documento',
  `nrow_linked` int NOT NULL DEFAULT '0' COMMENT 'Numero del rigo al quale è vincolato. Ad esempio un rigo tipo 6 (testo) derivante dalla descrizione estesa di un articolo/servizio di magazzino o, ad esempio, per creare task per la gestione dei diagrammi di Gantt',
  `id_tes` int NOT NULL,
  `tiprig` int NOT NULL,
  `transl_id_ref` int NOT NULL COMMENT 'Se > 0 è una referenza ad id_ref di gaz_001company_data dove riprendere i dati per la traduzione (o altro) nella lingua del partner',
  `codart` varchar(32) NOT NULL DEFAULT '',
  `codice_fornitore` varchar(50) NOT NULL DEFAULT '',
  `descri` varchar(1000) NOT NULL COMMENT '1000 caratteri per uniformarsi al tracciato della fattura elettronica',
  `quality` varchar(50) NOT NULL COMMENT 'per indicare la qualità del materiale richiesto, normativa, ecc',
  `id_body_text` int NOT NULL,
  `unimis` char(3) NOT NULL DEFAULT '',
  `larghezza` decimal(10,3) DEFAULT NULL COMMENT 'espresso in mm',
  `lunghezza` decimal(10,3) DEFAULT NULL COMMENT 'espresso in mm',
  `spessore` decimal(10,3) DEFAULT NULL COMMENT 'espresso in mm',
  `peso_specifico` decimal(10,3) DEFAULT NULL COMMENT 'non necessariamente in kg/l, potrà moltiplicare anche con i ml, mq, pezzi',
  `pezzi` int DEFAULT NULL,
  `quanti` decimal(14,5) DEFAULT NULL,
  `prelis` decimal(17,8) DEFAULT '0.00000000',
  `sconto` decimal(6,3) DEFAULT NULL,
  `codvat` int NOT NULL,
  `pervat` decimal(3,1) DEFAULT '0.0',
  `codric` int NOT NULL,
  `provvigione` decimal(4,2) NOT NULL COMMENT 'Provvigione in caso di agente oppure percentuale cassa previdenziale in caso di tipo rigo = 4',
  `ritenuta` decimal(3,1) NOT NULL,
  `id_order` int NOT NULL,
  `id_mag` int NOT NULL,
  `id_orderman` int NOT NULL COMMENT 'Ref. alla tabella gaz_001orderman (produzioni-contabilità industriale) ',
  `custom_field` text COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {"nome_modulo":{"nome_variabile":{"valore_variabile": {}}}}',
  `status` varchar(10) NOT NULL DEFAULT '',
  PRIMARY KEY (`id_rig`) USING BTREE,
  KEY `id_order` (`id_order`),
  KEY `id_tes` (`id_tes`),
  KEY `id_mag` (`id_mag`),
  KEY `codice_fornitore` (`codice_fornitore`),
  KEY `codart` (`codart`),
  KEY `tiprig` (`tiprig`),
  KEY `nrow` (`nrow`),
  KEY `nrow_linked` (`nrow_linked`),
  KEY `id_orderman` (`id_orderman`)
) ENGINE=MyISAM COMMENT='Righi dei documenti le cui testate sono contenute in gaz_NNNtesdoc';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001rigmoc`
--

DROP TABLE IF EXISTS `gaz_001rigmoc`;
CREATE TABLE IF NOT EXISTS `gaz_001rigmoc` (
  `id_rig` int NOT NULL AUTO_INCREMENT,
  `id_tes` int NOT NULL,
  `darave` char(1) NOT NULL DEFAULT '0',
  `codcon` int NOT NULL,
  `import` decimal(11,2) DEFAULT '0.00',
  `id_orderman` int NOT NULL COMMENT 'Ref. alla tabella gaz_001orderman (produzioni-contabilità industriale) ',
  PRIMARY KEY (`id_rig`) USING BTREE,
  KEY `codcon` (`codcon`),
  KEY `id_tes` (`id_tes`)
) ENGINE=MyISAM COMMENT='Righi dei movimenti contabili le cui testate sono contenute in gaz_NNNtesmov';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001rigmoi`
--

DROP TABLE IF EXISTS `gaz_001rigmoi`;
CREATE TABLE IF NOT EXISTS `gaz_001rigmoi` (
  `id_rig` int NOT NULL AUTO_INCREMENT,
  `id_tes` int NOT NULL,
  `tipiva` char(1) NOT NULL DEFAULT '0',
  `reverse_charge_idtes` int NOT NULL,
  `operation_type` varchar(15) NOT NULL,
  `codiva` int NOT NULL,
  `periva` decimal(3,1) DEFAULT '0.0',
  `imponi` decimal(11,2) DEFAULT '0.00',
  `impost` decimal(11,2) DEFAULT '0.00',
  PRIMARY KEY (`id_rig`) USING BTREE,
  KEY `id_tes` (`id_tes`),
  KEY `reverse_charge_idtes` (`reverse_charge_idtes`)
) ENGINE=MyISAM COMMENT='Righi dei movimenti IVA le cui testate sono contenute in gaz_NNNtesmov';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001room`
--

DROP TABLE IF EXISTS `gaz_001room`;
CREATE TABLE IF NOT EXISTS `gaz_001room` (
  `id_room` int NOT NULL AUTO_INCREMENT,
  `id_ward` int DEFAULT NULL,
  `roomname` varchar(50) NOT NULL DEFAULT '',
  `image` blob,
  `web_url` varchar(255) DEFAULT NULL,
  `custom_field` text COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {"nome_modulo":{"nome_variabile":{"valore_variabile": {}}}}',
  `note_other` varchar(50) DEFAULT NULL,
  `status` varchar(10) NOT NULL DEFAULT '',
  `adminid` varchar(20) NOT NULL DEFAULT '',
  `last_modified` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_room`) USING BTREE,
  KEY `id_ward` (`id_ward`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=MyISAM;

