--
-- Struttura della tabella `gaz_001staff_worked_hours`
--

DROP TABLE IF EXISTS `gaz_001staff_worked_hours`;
CREATE TABLE IF NOT EXISTS `gaz_001staff_worked_hours` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_staff` int NOT NULL,
  `work_day` date DEFAULT NULL,
  `hours_normal` decimal(4,2) NOT NULL,
  `id_work_type_extra` int NOT NULL,
  `hours_extra` decimal(4,2) NOT NULL,
  `id_absence_type` int NOT NULL,
  `hours_absence` decimal(4,2) NOT NULL,
  `id_other_type` int NOT NULL,
  `hours_other` decimal(4,2) NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `id_orderman` int DEFAULT NULL COMMENT 'sarà legato al piano dei conti per gestire le commesse (centri di costo)',
  `id_tes` int DEFAULT NULL COMMENT 'può essere usato per link con tesbro al fine di aver un documento/resoconto del lavoro eseguito',
  `custom_field` text COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {"nome_modulo":{"nome_variabile":{"valore_variabile": {}}}}',
  PRIMARY KEY (`id`),
  KEY `idx_id_staff` (`id_staff`) USING BTREE,
  KEY `work_day` (`work_day`),
  KEY `id_orderman` (`id_orderman`),
  KEY `id_tes` (`id_tes`)
) ENGINE=MyISAM COMMENT='Tabella contenente i dati per la generazione del "Registro delle presenze", ossia dei riepiloghi giornalieri delle ore/tipo di lavoro eseguito da ciascun lavoratore. Può essere scritta manualente dalla apposita interfaccia o, eventualemente, generata a fine mese dai movimenti registrati su gaz_NNNstaff_work_movements a sua volta frutto di inserimento manuale o se collegato tramite un marcatempo a badge.';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001staff_work_movements`
--

DROP TABLE IF EXISTS `gaz_001staff_work_movements`;
CREATE TABLE IF NOT EXISTS `gaz_001staff_work_movements` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_staff` int NOT NULL,
  `start_work` datetime DEFAULT NULL,
  `end_work` datetime DEFAULT NULL,
  `id_work_type` int NOT NULL COMMENT 'Quando riferito forza la scelta automatica. Esempio ''nromale'', straordinario, notturno',
  `min_delay` decimal(3,1) NOT NULL DEFAULT '0.0' COMMENT 'Minuti di ritardo',
  `hourly_cost` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT 'Costo orario',
  `note` varchar(255) DEFAULT NULL,
  `id_orderman` int DEFAULT NULL COMMENT 'sarà legato al piano dei conti per gestire le commesse (centri di costo)',
  `codice_campi` int DEFAULT NULL COMMENT 'riferimento alla tabella gaz_NNNcampi per indicare il luogo/reparto dove è stato eseguito il lavoro',
  `id_staff_worked_hours` int DEFAULT NULL COMMENT 'Se maggiore di 0 il rigo è già stato usato per calcolare il valore del rigo a cui si riferisce su gaz_NNN_staff_worked_hours',
  `custom_field` text COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {"nome_modulo":{"nome_variabile":{"valore_variabile": {}}}}',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id_staff` (`id_staff`) USING BTREE,
  KEY `id_orderman` (`id_orderman`) USING BTREE,
  KEY `work_day` (`start_work`) USING BTREE,
  KEY `id_tes` (`id_staff_worked_hours`) USING BTREE,
  KEY `end_work` (`end_work`),
  KEY `codice_campi` (`codice_campi`)
) ENGINE=MyISAM COMMENT='Tabella contenente i singoli movimenti del lavoratore. Può essere scritta manualente dalla apposita interfaccia o, se collegato, tramite un marcatempo a badge. Offre la possibilità di indicare la produzione/commessa (id_orderman) sulla quale sta lavorando.' ROW_FORMAT=DYNAMIC;

