DROP TABLE IF EXISTS `gaz_001tesbro`;
CREATE TABLE IF NOT EXISTS `gaz_001tesbro` (
  `id_tes` int NOT NULL AUTO_INCREMENT,
  `seziva` int NOT NULL COMMENT 'Nel modulo hospital contiene il letto ',
  `tipdoc` char(3) NOT NULL DEFAULT '',
  `tipdoc_buf` char(3) NOT NULL DEFAULT '' COMMENT 'Nel modulo hospital  il regime di ammissione: residenziale, semi-residenziale, day-hospital',
  `ref_ecommerce_id_order` varchar(50) DEFAULT '' COMMENT 'Identificativo ordine attribuito dall''eventuale ecommerce collegato attraverso API',
  `template` varchar(32) DEFAULT '',
  `email` varchar(50) DEFAULT '' COMMENT 'Utilizzato per inviare i documenti ad un indirizzo diverso da quello in anagrafica',
  `print_total` int NOT NULL,
  `delivery_time` int NOT NULL,
  `day_of_validity` int NOT NULL,
  `datemi` date DEFAULT '2004-01-27',
  `weekday_repeat` int NOT NULL,
  `protoc` int NOT NULL,
  `numdoc` bigint NOT NULL,
  `numfat` varchar(20) NOT NULL DEFAULT '0',
  `datfat` date DEFAULT '2004-01-27',
  `clfoco` int NOT NULL,
  `pagame` int NOT NULL,
  `banapp` int NOT NULL,
  `vettor` int NOT NULL,
  `listin` int NOT NULL,
  `destin` varchar(100) NOT NULL,
  `id_des` int NOT NULL,
  `id_des_same_company` int NOT NULL,
  `spediz` varchar(50) NOT NULL DEFAULT '',
  `portos` varchar(50) NOT NULL DEFAULT '',
  `imball` varchar(50) NOT NULL DEFAULT '',
  `traspo` decimal(6,2) DEFAULT '0.00',
  `speban` decimal(6,2) DEFAULT '0.00',
  `spevar` decimal(6,2) DEFAULT '0.00',
  `round_stamp` tinyint NOT NULL DEFAULT '5',
  `cauven` int NOT NULL,
  `caucon` char(3) NOT NULL,
  `caumag` int NOT NULL,
  `id_agente` int NOT NULL,
  `id_parent_doc` int NOT NULL COMMENT 'riferimento ad id_tes del documento genitore  (es. ordine riferito a preventivo genitore)',
  `sconto` decimal(5,2) DEFAULT '0.00',
  `expense_vat` int NOT NULL,
  `stamp` decimal(6,2) NOT NULL,
  `taxstamp` decimal(5,2) NOT NULL,
  `virtual_taxstamp` tinyint NOT NULL,
  `net_weight` decimal(12,2) NOT NULL,
  `gross_weight` decimal(12,2) NOT NULL,
  `units` int NOT NULL,
  `volume` decimal(8,2) NOT NULL,
  `initra` datetime DEFAULT '2004-01-27 18:20:00',
  `id_signature` int DEFAULT NULL COMMENT 'riferimento ad id_body tabella gaz_NNNbody_text per contenere l''eventuale firma (immagine/elettronica) ',
  `geneff` char(1) NOT NULL DEFAULT '',
  `id_contract` int NOT NULL,
  `id_con` int NOT NULL COMMENT 'Nel modulo hospital è usato per l''id_patient',
  `id_orderman` int NOT NULL COMMENT 'Nel modulo hospital viene usato per riferire il documento ad id_tes dell''ammissione(ricovero) ',
  `status` varchar(10) NOT NULL DEFAULT '',
  `custom_field` text COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {"nome_modulo":{"nome_variabile":{"valore_variabile": {}}}}',
  `adminid` varchar(20) NOT NULL DEFAULT '',
  `last_modified` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_tes`),
  KEY `idx_seziva` (`seziva`) USING BTREE,
  KEY `idx_datemi` (`datemi`) USING BTREE,
  KEY `ref_ecommerce_id_order` (`ref_ecommerce_id_order`),
  KEY `numdoc` (`numdoc`),
  KEY `clfoco` (`clfoco`),
  KEY `id_contract` (`id_contract`),
  KEY `id_con` (`id_con`),
  KEY `id_orderman` (`id_orderman`),
  KEY `tipdoc` (`tipdoc`),
  KEY `tipdoc_buf` (`tipdoc_buf`)
) ENGINE=MyISAM COMMENT='Testate documenti che non hanno valenza fiscale. Ordini, preventivi, commesse, ecc';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001tesdoc`
--

DROP TABLE IF EXISTS `gaz_001tesdoc`;
CREATE TABLE IF NOT EXISTS `gaz_001tesdoc` (
  `id_tes` int NOT NULL AUTO_INCREMENT,
  `seziva` int NOT NULL,
  `tipdoc` char(3) NOT NULL DEFAULT '',
  `tipdoc_buf` char(3) NOT NULL DEFAULT '' COMMENT 'Quando tipdoc sarà valorizzato con "BUF", potrò utilizzare questa colonna per indicare il valore che dovrà assumere la colonna tipdoc alla conferma del contenuto del documento che si sta inserendo, questo eviterà in futuro (o a chi personalizza qualche interfaccia utente) di fare il POST di tutti i righi già immessi superando il limite attuale imposto dalla direttiva  max_input_vars del PHP. In sostanza si potrà mettere sempre e subito tutto sul database man mano che vengono inseriti i righi per poi valorizzare con il giusto tipdoc alla conferma. Il tipdoc=BUF dovrà essere uno solo per ogni utente (colonna adminid) e quindi ripulito ad ogni nuovo documento perché potrebbe essere rimasto in sospeso con un precedente documento mai confermato',
  `ddt_type` char(1) NOT NULL,
  `id_doc_ritorno` int NOT NULL,
  `template` varchar(32) DEFAULT '',
  `email` varchar(50) DEFAULT '' COMMENT 'Utilizzato per inviare i documenti ad un indirizzo diverso da quello in anagrafica',
  `datemi` date DEFAULT '2004-01-27',
  `weekday_repeat` int NOT NULL,
  `data_ordine` date DEFAULT '2004-01-27',
  `protoc` int NOT NULL,
  `numdoc` int NOT NULL,
  `numfat` varchar(20) NOT NULL DEFAULT '0',
  `datfat` date DEFAULT '2004-01-27',
  `clfoco` int NOT NULL,
  `pagame` int NOT NULL,
  `ragbol` int NOT NULL,
  `banapp` int NOT NULL,
  `vettor` int NOT NULL,
  `listin` int NOT NULL,
  `destin` varchar(100) NOT NULL,
  `id_des` int NOT NULL,
  `id_des_same_company` int NOT NULL,
  `spediz` varchar(50) NOT NULL DEFAULT '',
  `portos` varchar(50) NOT NULL DEFAULT '',
  `imball` varchar(50) NOT NULL DEFAULT '',
  `traspo` decimal(6,2) DEFAULT '0.00',
  `speban` decimal(6,2) DEFAULT '0.00',
  `spevar` decimal(6,2) DEFAULT '0.00',
  `round_stamp` tinyint NOT NULL DEFAULT '5',
  `cauven` int NOT NULL,
  `caucon` char(3) NOT NULL,
  `caumag` int NOT NULL,
  `id_agente` int NOT NULL,
  `id_parent_doc` int NOT NULL COMMENT 'riferimento ad id_tes del documento genitore  (es. ordine riferito a preventivo genitore)',
  `sconto` decimal(5,2) DEFAULT '0.00',
  `expense_vat` int NOT NULL,
  `stamp` decimal(6,2) NOT NULL,
  `taxstamp` decimal(5,2) NOT NULL,
  `virtual_taxstamp` tinyint NOT NULL,
  `net_weight` decimal(12,2) NOT NULL,
  `gross_weight` decimal(12,2) NOT NULL,
  `units` int NOT NULL,
  `volume` decimal(8,2) NOT NULL,
  `initra` datetime DEFAULT '2004-01-27 18:20:00',
  `geneff` char(1) NOT NULL DEFAULT '',
  `id_contract` int NOT NULL COMMENT 'In caso di corrispettivo, scontrino con causale VCO, viene usato per contenere l''id del registratore ovvero id_cash della tabella gaz_NNNcash_register, se "0" verrà generato un file XML, altrimenti verranno inviati i dati al RT in base a quanto indicato sul rigo della tabella citata',
  `id_con` int NOT NULL,
  `datreg` date DEFAULT NULL COMMENT 'Data in cui si vuole venga registrata in contabilità la fattura d''acquisto (prima veniva messo in impropriamente in datemi)',
  `fattura_elettronica_zip_package` varchar(100) DEFAULT NULL COMMENT 'Nome del file zip in cui è contenuto la fattura elettronica',
  `fattura_elettronica_original_name` varchar(100) DEFAULT NULL,
  `fattura_elettronica_original_content` mediumblob,
  `fattura_elettronica_reinvii` int DEFAULT '0' COMMENT 'Numero di reinvii allo SdI della fattura elettronica, assieme alla sezione, alla data fattura e al numero di protocollo e dopo un encode in base 36 determinerà gli ultimi cinque caratteri del nome file',
  `status` varchar(10) NOT NULL DEFAULT '',
  `custom_field` text COMMENT 'Usabile per contenere le scelte dell''utente in ambito dello specifico modulo. Normalmente in formato json: {"nome_modulo":{"nome_variabile": {"valorei_variabile"}}',
  `adminid` varchar(20) NOT NULL DEFAULT '',
  `last_modified` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_tes`),
  KEY `tipdoc` (`tipdoc`),
  KEY `datfat` (`datfat`),
  KEY `numfat` (`numfat`),
  KEY `idx_tipdoc1` (`tipdoc`(1)) USING BTREE,
  KEY `idx_seziva` (`seziva`) USING BTREE,
  KEY `idx_protoc` (`protoc`) USING BTREE,
  KEY `datreg` (`datreg`),
  KEY `clfoco` (`clfoco`),
  KEY `datemi` (`datemi`),
  KEY `fattura_elettronica_zip_package` (`fattura_elettronica_zip_package`),
  KEY `ddt_type` (`ddt_type`),
  KEY `id_contract` (`id_contract`),
  KEY `id_con` (`id_con`),
  KEY `tipdoc_buf` (`tipdoc_buf`)
) ENGINE=MyISAM COMMENT='Testate documenti fiscalmente validi. Fatture, Note credito, , Documenti di Trasporto, ecc';

-- --------------------------------------------------------

--
-- Struttura della tabella `gaz_001tesmov`
--

DROP TABLE IF EXISTS `gaz_001tesmov`;
CREATE TABLE IF NOT EXISTS `gaz_001tesmov` (
  `id_tes` int NOT NULL AUTO_INCREMENT,
  `caucon` char(3) NOT NULL DEFAULT '',
  `caucon_buf` char(3) NOT NULL DEFAULT '' COMMENT 'Quando caucon sarà valorizzato con "BUF", potrò utilizzare questa colonna per indicare il valore che dovrà assumere la colonna caucon alla conferma del contenuto del movimento che si sta inserendo, questo eviterà in futuro o a chi personalizza l''interfaccia utente di fare il POST di tutti i righi già immessi superando il limite attuale imposto dalla direttiva  max_input_vars del PHP. In sostanza si potrà mettere sempre e subito tutto sul database man mano che vengono inseriti i righi per poi valorizzare con la giusta causale alla conferma. Il tipdoc=BUF dovrà essere uno solo per ogni utente (colonna adminid) e quindi ripulito ad ogni nuovo movimento contabile perché potrebbe essere rimasto in sospeso con un precedente  mai confermato',
  `descri` varchar(100) NOT NULL DEFAULT '',
  `notess` text COMMENT 'Note che NON vengono stampate sui registri contabili',
  `datreg` date DEFAULT '2004-01-27',
  `datliq` date DEFAULT '2004-01-27' COMMENT 'Data di riferimento del periodo della liquidazione periodica dell''IVA, non può precedere la data del documento (datdoc)',
  `seziva` int NOT NULL,
  `id_doc` int NOT NULL,
  `protoc` int NOT NULL,
  `numdoc` varchar(20) NOT NULL DEFAULT '0',
  `datdoc` date DEFAULT '2004-01-27',
  `clfoco` int NOT NULL,
  `regiva` char(1) NOT NULL DEFAULT '',
  `operat` int NOT NULL,
  `libgio` char(1) NOT NULL DEFAULT '',
  `adminid` varchar(20) NOT NULL DEFAULT '',
  `last_modified` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_tes`),
  KEY `datreg` (`datreg`),
  KEY `datliq` (`datliq`),
  KEY `clfoco` (`clfoco`),
  KEY `caucon` (`caucon`),
  KEY `caucon_buf` (`caucon_buf`)
) ENGINE=MyISAM COMMENT='Testate dei movimenti contabili';

