  `impimb` int NOT NULL,
  `impspe` int NOT NULL,
  `impvar` int NOT NULL,
  `boleff` int NOT NULL COMMENT 'Conto dei ricavi per bolli su vendite (il conto di costo su acquisti è la colonna taxstamp_account)',
  `omaggi` int NOT NULL,
  `sales_return` int NOT NULL,
