--
-- Struttura della tabella `gaz_students`
--

DROP TABLE IF EXISTS `gaz_students`;
CREATE TABLE IF NOT EXISTS `gaz_students` (
  `student_id` int NOT NULL AUTO_INCREMENT COMMENT 'auto incrementing student_id of each student, unique index',
  `student_classroom_id` int NOT NULL COMMENT 'classroom_id of student',
  `student_firstname` varchar(30) NOT NULL COMMENT 'student''s first name',
  `student_lastname` varchar(30) NOT NULL COMMENT 'student''s last name',
  `student_name` varchar(64) NOT NULL COMMENT 'student''s name, unique',
  `student_password_hash` varchar(255) NOT NULL COMMENT 'student''s password in salted and hashed format',
  `student_email` varchar(64) NOT NULL COMMENT 'student''s email, unique',
  `student_telephone` varchar(30) NOT NULL COMMENT 'student''s telephone number',
  `student_active` tinyint NOT NULL COMMENT 'student''s activation status',
  `student_activation_hash` varchar(40) DEFAULT NULL COMMENT 'student''s email verification hash string',
  `student_password_reset_hash` char(40) DEFAULT NULL COMMENT 'student''s password reset code',
  `student_password_reset_timestamp` bigint DEFAULT NULL COMMENT 'timestamp of the password reset request',
  `student_rememberme_token` varchar(64) DEFAULT NULL COMMENT 'student''s remember-me cookie token',
  `student_failed_logins` tinyint NOT NULL COMMENT 'student''s failed login attemps',
  `student_last_failed_login` int DEFAULT NULL COMMENT 'unix TIMESTAMP of last failed login attempt',
  `student_registration_datetime` datetime NOT NULL,
  `student_registration_ip` varchar(39) NOT NULL DEFAULT '0.0.0.0',
  PRIMARY KEY (`student_id`),
  UNIQUE KEY `student_name` (`student_name`),
  UNIQUE KEY `student_email` (`student_email`)
) ENGINE=MyISAM COMMENT='student data';
COMMIT;
